const warned = new Set<string>();

/**
 * DEV 期一次性告警。同一 `key` 全程只警一次。这些告警都在 render 或每渲染的 effect 里调用，
 * 不去重会刷屏。`key` 只用于去重、不出现在输出里；`message` 自带来源前缀。
 *
 * 生产构建下 `import.meta.env.DEV` 是字面 `false`，整个函数体被 DCE 掉。该守卫依赖 Vite 的
 * `import.meta.env`（TanStack Start 即 Vite）；非 Vite 构建下需自行替换成等价的环境判断。
 */
export function devWarn(key: string, message: string): void {
  if (!import.meta.env.DEV) return;
  if (warned.has(key)) return;
  warned.add(key);
  console.warn(message);
}

import {
  type ColumnDef,
  columnVisibilityFeature,
  createColumnHelper,
  type ReactTable,
  type Row,
  type RowData,
  rowPaginationFeature,
  rowSelectionFeature,
  rowSortingFeature,
  type Table,
  type TableState,
  tableFeatures,
} from "@tanstack/react-table";
import type { ReactNode } from "react";

/** 列 `meta` 的形状。经 `baseFeatureMap` 的 `columnMeta` 槽按表声明，不走全局 `declare module`：
 *  本文件是 copy-in 分发的，全局增广会污染下游项目的类型空间，下游再增广同一接口即冲突。 */
export interface TableColumnMeta {
  align?: "left" | "right" | "center";
  className?: string;
  label?: ReactNode;
  /** 横向滚动时固定在左侧。一张表只认第一个声明它的列，且该列应排在最前（勾选列之后）：
   *  固定的是「这条记录是谁」，排在中间的列固定住，前面的列会从它底下滑过去。 */
  sticky?: boolean;
}

/** 基础特性映射；供 DataTable 与调用方追加特性时做加法合并。
 *
 *  `columnMeta` 必须挂在这里而不是 `tableFeatures()` 调用处：`useDataTable` 用
 *  `tableFeatures({ ...baseFeatureMap, ...opts.features })` 做加法合并，槽写在调用处的话，
 *  调用方一传 `features` 就把它挤掉了。挂在 map 上则天然幸存，并顺带给下游一个扩展点——
 *  传 `columnMeta: {} as TableColumnMeta & { mine: X }` 即可加自己的键。 */
export const baseFeatureMap = {
  rowSortingFeature,
  rowPaginationFeature,
  columnVisibilityFeature,
  rowSelectionFeature,
  // 幻影值：运行时被剥离，只有类型参与推断。
  columnMeta: {} as TableColumnMeta,
};

/** 全表共用的 v9 特性集；少注册一个对应方法即编译期消失。 */
export const features = tableFeatures(baseFeatureMap);

export type TableFeatures = typeof features;

/** 下游经 `useDataTable({ features })` 追加的特性映射。 */
export type ExtraFeatureMap = Parameters<typeof tableFeatures>[0];

/** 没有追加特性。用作各类型别名第二参数的缺省值，现有的单参数写法因此不受影响。 */
export type NoExtraFeatures = Record<never, never>;

/** 基础特性并上追加特性后的完整特性集。 */
export type TableFeaturesWith<TExtra extends ExtraFeatureMap = NoExtraFeatures> =
  typeof baseFeatureMap & TExtra;

/** `useDataTable` 让宿主订阅的状态投影。少了 `rowSelection`：那一片由表头、行、`SelectedCount`
 * 各自定点订阅，宿主不为勾选重渲染，所以 `table.state` 里也读不到它——要读走
 * `table.atoms.rowSelection.get()`（快照）或 `Subscribe`（订阅）。 */
export type HostTableState<TExtra extends ExtraFeatureMap = NoExtraFeatures> = Omit<
  TableState<TableFeaturesWith<TExtra>>,
  "rowSelection"
>;

/** DataTable 内部构造的表实例类型。`useDataTable()` 的调用方在自己的组件作用域里直接拿到它
 * （`dt.table`）；`DataTable` 的 `footer` 回调另外单独给一份。传了 `TExtra` 时，追加特性的
 * API（如 `rowExpandingFeature` 的 `toggleAllRowsExpanded`）在类型上可见。 */
export type TableInstance<
  TData extends RowData,
  TExtra extends ExtraFeatureMap = NoExtraFeatures,
> = ReactTable<TableFeaturesWith<TExtra>, TData, HostTableState<TExtra>>;

/** 列 `cell` 上下文给出的表对象类型，比 `TableInstance` 窄。`ReactTable` 是
 * `Omit<Table, "store"> & { store, state, Subscribe, FlexRender }`，而 `state`/`Subscribe`/
 * `FlexRender` 只挂在 `useTable()` 另行 memo 出的返回对象上，cell 上下文永远拿不到。故行内插槽
 * （`AbpTableRowConfig` 的 `actions`/`menu`，喂给 `RowActionsMenu` 的 `rowActions`/`items` 属性）
 * 一律用这个类型，宁可少承诺也不给说谎的类型；
 * 要读当前状态走 `table.atoms.<slice>.get()`（快照），要订阅用从 `@tanstack/react-table`
 * 直接导入的 `Subscribe` 配 `source={table.atoms.<slice>}`——`table.state` / `table.Subscribe`
 * 只挂在 `useTable()` 的返回对象上，这里没有；`table.store` 在 v9 已废弃，勿用。要完整
 * 实例走调用方自己持有的 `dt.table` 或 `DataTable` 的 `footer` 回调。 */
export type CellTableInstance<
  TData extends RowData,
  TExtra extends ExtraFeatureMap = NoExtraFeatures,
> = Table<TableFeaturesWith<TExtra>, TData>;

/** 绑定好特性集的行类型；`DataTable` 的行级插槽收这个。 */
export type TableRowInstance<
  TData extends RowData,
  TExtra extends ExtraFeatureMap = NoExtraFeatures,
> = Row<TableFeaturesWith<TExtra>, TData>;

/** 绑定好 TFeatures 的列定义别名，消费方只写这个，不感知泛型。追加了特性的表传第二参数，
 *  列的 cell 里才点得出那些特性的行 API。 */
export type TableColumnDef<
  TData extends RowData,
  TExtra extends ExtraFeatureMap = NoExtraFeatures,
> = ColumnDef<TableFeaturesWith<TExtra>, TData, unknown>;

export const createTableColumnHelper = <
  TData extends RowData,
  TExtra extends ExtraFeatureMap = NoExtraFeatures,
>() => createColumnHelper<TableFeaturesWith<TExtra>, TData>();

/** 把追加了特性的表收窄回基础特性集，供内置组件消费。
 *
 *  v9 的 `Table`/`Row` 泛型是 `in out`（不变）的，`Base & Extra` 的表赋不给按 `Base` 定型的
 *  组件；而把组件改成对特性集泛型又不行——成员类型由特性映射展开，泛型下推迟求值，组件内部
 *  一个基础 API 都点不出来。运行时追加特性只多不少，基础 API 必然都在，所以集中在这一处断言，
 *  不让强转散落到各组件。 */
export function asBaseTable<TData extends RowData, TExtra extends ExtraFeatureMap>(
  table: TableInstance<TData, TExtra>,
): TableInstance<TData> {
  return table as unknown as TableInstance<TData>;
}

import {
  functionalUpdate,
  type PaginationState,
  type SortingState,
  type Updater,
} from "@tanstack/react-table";
import { useCallback, useMemo, useRef, useState, useSyncExternalStore } from "react";

export type TableDensity = "comfortable" | "compact";

/** 列表的「位置」：翻到哪一页、每页几条、怎么排、搜的什么。这四样决定了请求参数，
 *  也正是从详情页返回、刷新、分享链接时该原样恢复的东西。 */
export interface DataTableListState {
  pageIndex: number;
  pageSize: number;
  sorting: SortingState;
  filter: string;
}

/**
 * 把列表位置交给外部持有（典型是 URL search params）。给了它，状态机不再自己存这四样：
 * 读 `value`，变更时把完整的下一状态交给 `onChange`，由持有方写回并触发重渲染。
 *
 * `value` 缺的键回落到默认值（第 1 页、默认每页条数、无排序、空搜索），所以一条干净的 URL
 * 就是默认状态。两个成员都不需要引用稳定。
 */
export interface DataTableListStore {
  value: Partial<DataTableListState>;
  onChange: (next: DataTableListState) => void;
}

/** 跟着人走、不跟着链接走的视图偏好。 */
export interface DataTablePreferences {
  density?: TableDensity;
  pageSize?: number;
  /** 列 id → 是否可见；只记用户动过的列。 */
  columnVisibility?: Record<string, boolean>;
}

/**
 * 视图偏好的存取适配器，形状即 `useSyncExternalStore` 的契约：`get` 在两次变更之间必须返回
 * 同一个引用，`set` 之后通知订阅者。内建实现见 `localStoragePreferences`；要存到别处
 * （如 ABP 的用户设置）照这个形状自己实现。实例引用必须稳定。
 */
export interface DataTablePreferenceStore {
  subscribe: (onChange: () => void) => () => void;
  get: () => DataTablePreferences;
  set: (next: DataTablePreferences) => void;
}

export interface UseDataTableStateOptions {
  defaultPageSize?: number;
  /** 搜索框的初始值（深链预填），只在挂载时播种一次。给了 `list` 时不生效，搜索值以它为准。 */
  initialFilter?: string;
  list?: DataTableListStore;
  preferences?: DataTablePreferenceStore;
}

const NO_PREFERENCES: DataTablePreferences = {};
const NO_SORTING: SortingState = [];
const subscribeToNothing = () => () => {};
const getNoPreferences = () => NO_PREFERENCES;

function sameSorting(a: SortingState, b: SortingState): boolean {
  return a.length === b.length && a.every((s, i) => s.id === b[i]?.id && s.desc === b[i]?.desc);
}

function sameListState(a: DataTableListState, b: DataTableListState): boolean {
  return (
    a.pageIndex === b.pageIndex &&
    a.pageSize === b.pageSize &&
    a.filter === b.filter &&
    sameSorting(a.sorting, b.sorting)
  );
}

/**
 * 服务端分页表格的状态机：分页/排序/已提交搜索值；filter 为已提交的搜索值，
 * 输入框即时值与防抖由工具条自己持有（见 DataTableToolbar），状态机只接收提交结果。
 * 行选择不在这里——所有权在表实例上（`table.atoms.rowSelection`），经 `useDataTable` 暴露。
 * 结构化查询参数不归这里管，那是 useAbpTable 的表单实例自己持有的东西。
 *
 * 缺省全部存在组件内，卸载即丢。`list` 把列表位置交给外部持有，`preferences` 把密度、
 * 每页条数和列显隐存下来；两者独立，按页选用。
 */
export function useDataTableState(opts: UseDataTableStateOptions = {}) {
  const defaultPageSize = opts.defaultPageSize ?? 10;
  const preferenceStore = opts.preferences;
  // 服务端快照恒为空：SSR 读不到本机偏好。水合时 React 先按空偏好对上服务端 HTML，再在
  // 副作用之前同步重渲染一次换成真实偏好，取数（在副作用里发起）因此只会按最终的每页条数发一次。
  const preferences = useSyncExternalStore(
    preferenceStore?.subscribe ?? subscribeToNothing,
    preferenceStore?.get ?? getNoPreferences,
    getNoPreferences,
  );

  const [local, setLocal] = useState<DataTableListState>(() => ({
    pageIndex: 0,
    pageSize: defaultPageSize,
    sorting: NO_SORTING,
    filter: opts.initialFilter ?? "",
  }));
  const [localDensity, setLocalDensity] = useState<TableDensity>("comfortable");

  // 「当前这一页的语境」的版本号。resetPaging 每次都递增，哪怕 pageIndex 写回同值：
  // 用户本来就在第 1 页时分页/排序/搜索三者可以一起纹丝不动（查询面板提交只改结构化参数），
  // 光比这三样看不出语境换过，页内选择就会跨语境残留。选中态归表所有，清空动作在
  // useDataTable 里按这个版本号触发（见那边的 scopeKey effect）。
  const [scopeEpoch, setScopeEpoch] = useState(0);

  const held: Partial<DataTableListState> = opts.list ? opts.list.value : local;
  // 外部持有时链接里的每页条数优先于个人偏好：分享出去的「第 3 页」得是同一个第 3 页。
  const pageSize = opts.list
    ? (held.pageSize ?? preferences.pageSize ?? defaultPageSize)
    : (preferences.pageSize ?? local.pageSize);
  const pageIndex = held.pageIndex ?? 0;
  const filter = held.filter ?? "";

  // 外部持有方每次渲染解析出的都是新数组；内容没变就沿用旧引用，免得表实例把它当成排序变了。
  const sortingRef = useRef<SortingState>(NO_SORTING);
  const heldSorting = held.sorting ?? NO_SORTING;
  if (!sameSorting(sortingRef.current, heldSorting)) sortingRef.current = heldSorting;
  const sorting = sortingRef.current;

  const pagination = useMemo<PaginationState>(
    () => ({ pageIndex, pageSize }),
    [pageIndex, pageSize],
  );

  // 变更函数全部经 ref 读「此刻的值」和外部适配器：它们的引用因此恒定（进了下游的 effect
  // 依赖），而同一个事件处理里连着两次变更（提交搜索 = 写搜索值 + 回第 1 页）也能叠加，
  // 不会后一次拿着旧值把前一次盖掉。
  const currentRef = useRef<DataTableListState>({ pageIndex, pageSize, sorting, filter });
  currentRef.current = { pageIndex, pageSize, sorting, filter };
  const listRef = useRef(opts.list);
  listRef.current = opts.list;

  const update = useCallback(
    (change: (previous: DataTableListState) => DataTableListState) => {
      const previous = currentRef.current;
      const next = change(previous);
      if (sameListState(previous, next)) return;
      currentRef.current = next;
      if (listRef.current) listRef.current.onChange(next);
      else setLocal(next);
      if (preferenceStore && next.pageSize !== previous.pageSize) {
        preferenceStore.set({ ...preferenceStore.get(), pageSize: next.pageSize });
      }
    },
    [preferenceStore],
  );

  const resetPaging = useCallback(() => {
    // 新查询从第一页开始，否则会停留在越界页
    update((previous) => ({ ...previous, pageIndex: 0 }));
    setScopeEpoch((n) => n + 1);
  }, [update]);

  /** 提交搜索值：写入已提交的 filter 并回到第 1 页。防抖由调用方负责——
   *  输入节奏是输入框自己的事，放进状态机就必须把即时值也留在页面级，
   *  那正是「敲一个字母整表重画」的来源。 */
  const commitSearch = useCallback(
    (value: string) => {
      update((previous) => ({ ...previous, filter: value, pageIndex: 0 }));
      setScopeEpoch((n) => n + 1);
    },
    [update],
  );

  const onPaginationChange = useCallback(
    (updater: Updater<PaginationState>) => {
      update((previous) => ({
        ...previous,
        ...functionalUpdate(updater, {
          pageIndex: previous.pageIndex,
          pageSize: previous.pageSize,
        }),
      }));
    },
    [update],
  );
  const onSortingChange = useCallback(
    (updater: Updater<SortingState>) => {
      update((previous) => ({ ...previous, sorting: functionalUpdate(updater, previous.sorting) }));
    },
    [update],
  );

  const setDensity = useCallback(
    (density: TableDensity) => {
      if (preferenceStore) preferenceStore.set({ ...preferenceStore.get(), density });
      else setLocalDensity(density);
    },
    [preferenceStore],
  );

  /** 密度与每页条数回默认值。列显隐不在这里：那一片归表实例，调用方另行
   *  `table.resetColumnVisibility()`（见 `DataTableViewMenu`）。 */
  const resetViewDefaults = useCallback(() => {
    if (preferenceStore) {
      const { columnVisibility } = preferenceStore.get();
      preferenceStore.set(columnVisibility ? { columnVisibility } : {});
    } else setLocalDensity("comfortable");
    update((previous) =>
      previous.pageSize === defaultPageSize
        ? previous
        : { ...previous, pageSize: defaultPageSize, pageIndex: 0 },
    );
  }, [preferenceStore, update, defaultPageSize]);

  /** 只在接了偏好存储时有值；没接时列显隐留给表实例自管，这里不插手。 */
  const setColumnVisibility = useMemo(
    () =>
      preferenceStore
        ? (columnVisibility: Record<string, boolean>) =>
            preferenceStore.set({ ...preferenceStore.get(), columnVisibility })
        : undefined,
    [preferenceStore],
  );

  return {
    params: { pageIndex, pageSize, sorting, filter },
    pagination,
    sorting,
    scopeEpoch,
    commitSearch,
    resetPaging,
    onPaginationChange,
    onSortingChange,
    density: preferences.density ?? localDensity,
    setDensity,
    defaultPageSize,
    resetViewDefaults,
    /** 已存下来的列显隐；用户没动过任何列时为 undefined。 */
    columnVisibility: preferences.columnVisibility,
    setColumnVisibility,
  };
}

export type DataTableState = ReturnType<typeof useDataTableState>;

import type {
  DataTablePreferenceStore,
  DataTablePreferences,
} from "@/components/data-table/use-data-table-state";

const EMPTY: DataTablePreferences = {};
const stores = new Map<string, DataTablePreferenceStore>();

/** 存储里的内容不可信：可能是旧版本写的、别的代码写的，或被手改过。逐键收窄，认不出的丢掉。 */
function parse(raw: string | null): DataTablePreferences {
  if (raw === null) return EMPTY;
  let value: unknown;
  try {
    value = JSON.parse(raw);
  } catch {
    return EMPTY;
  }
  if (typeof value !== "object" || value === null) return EMPTY;
  const { density, pageSize, columnVisibility } = value as Record<string, unknown>;
  const result: DataTablePreferences = {};
  if (density === "comfortable" || density === "compact") result.density = density;
  if (typeof pageSize === "number" && Number.isInteger(pageSize) && pageSize > 0) {
    result.pageSize = pageSize;
  }
  if (typeof columnVisibility === "object" && columnVisibility !== null) {
    result.columnVisibility = Object.fromEntries(
      Object.entries(columnVisibility).filter(
        (entry): entry is [string, boolean] => typeof entry[1] === "boolean",
      ),
    );
  }
  return result;
}

/**
 * 把表格的视图偏好（密度、每页条数、列显隐）存进 `localStorage`，键为 `data-table:<key>`。
 * `key` 按表取名并保持稳定（如 `"identity-users"`）：改名等于丢掉所有用户已存的偏好，
 * 两张表共用一个名字则会互相覆盖。
 *
 * 同名多次调用返回同一个实例，可以直接写在渲染里。存储不可用（隐私模式、被禁用）时退化为
 * 只在本次会话内记住，不抛错。其他标签页的修改经 `storage` 事件同步过来。
 */
export function localStoragePreferences(key: string): DataTablePreferenceStore {
  const existing = stores.get(key);
  if (existing) return existing;

  const storageKey = `data-table:${key}`;
  const listeners = new Set<() => void>();
  // `undefined` 表示还没读过，与「读过、没有值」的 null 区分开。
  let raw: string | null | undefined;
  let value = EMPTY;
  let storageFailed = false;

  const store: DataTablePreferenceStore = {
    subscribe(onChange) {
      listeners.add(onChange);
      const onStorage = (event: StorageEvent) => {
        if (event.key === storageKey || event.key === null) onChange();
      };
      window.addEventListener("storage", onStorage);
      return () => {
        listeners.delete(onChange);
        window.removeEventListener("storage", onStorage);
      };
    },
    get() {
      if (storageFailed) return value;
      let current: string | null;
      try {
        current = window.localStorage.getItem(storageKey);
      } catch {
        storageFailed = true;
        return value;
      }
      // 只在原文变了时重新解析：useSyncExternalStore 要求快照在两次变更之间引用不变。
      if (current !== raw) {
        raw = current;
        value = parse(current);
      }
      return value;
    },
    set(next) {
      value = next;
      raw = JSON.stringify(next);
      try {
        window.localStorage.setItem(storageKey, raw);
      } catch {
        storageFailed = true;
      }
      for (const listener of listeners) listener();
    },
  };
  stores.set(key, store);
  return store;
}

import type { SortingState } from "@tanstack/react-table";
import type {
  DataTableListState,
  DataTableListStore,
} from "@/components/data-table/use-data-table-state";

/**
 * 列表位置在 URL 里的形状：`?page=3&size=20&sort=name,-creationTime&q=foo`。
 * 页码从 1 起（给人看的），排序是逗号分隔的列 id，前缀 `-` 表示降序。
 * 等于默认值的键不出现，默认状态就是一条干净的 URL。
 */
export interface ListSearch {
  page?: number;
  size?: number;
  sort?: string;
  q?: string;
}

function positiveInteger(value: unknown): number | undefined {
  return typeof value === "number" && Number.isInteger(value) && value > 0 ? value : undefined;
}

/**
 * 路由的 `validateSearch`：从原始 search 里取出列表位置的四个键，认不出的值当作没给。
 * 页面还有别的 search 参数时，在自己的 `validateSearch` 里把它的结果展开进去。
 * URL 是用户能随手改的输入，这里不抛错——一个写坏的 `page=abc` 不该让整页进错误边界。
 */
export function parseListSearch(search: Record<string, unknown>): ListSearch {
  const result: ListSearch = {};
  const page = positiveInteger(search.page);
  const size = positiveInteger(search.size);
  if (page !== undefined) result.page = page;
  if (size !== undefined) result.size = size;
  if (typeof search.sort === "string" && search.sort !== "") result.sort = search.sort;
  // 纯数字的搜索词会被路由的 search 解析成 number，按字符串收回来。
  if (typeof search.q === "string" && search.q !== "") result.q = search.q;
  else if (typeof search.q === "number") result.q = String(search.q);
  return result;
}

function parseSort(sort: string): SortingState {
  return sort
    .split(",")
    .filter((part) => part !== "" && part !== "-")
    .map((part) =>
      part.startsWith("-") ? { id: part.slice(1), desc: true } : { id: part, desc: false },
    );
}

/** URL → 列表位置，喂给 `DataTableListStore.value`。缺的键留空，由状态机回落到默认值。 */
export function listStateFromSearch(search: ListSearch): Partial<DataTableListState> {
  const state: Partial<DataTableListState> = {};
  if (search.page !== undefined) state.pageIndex = search.page - 1;
  if (search.size !== undefined) state.pageSize = search.size;
  if (search.sort !== undefined) state.sorting = parseSort(search.sort);
  if (search.q !== undefined) state.filter = search.q;
  return state;
}

/**
 * 列表位置 → URL，在 `DataTableListStore.onChange` 里展开进 `navigate({ search })`。
 * 四个键总是都返回，等于默认值的给 `undefined`：路由据此把它从 URL 里删掉，而不是留着旧值。
 * `defaultPageSize` 要与传给表格的一致，否则默认每页条数会被当成非默认值写进 URL。
 */
export function listStateToSearch(
  state: DataTableListState,
  options: { defaultPageSize?: number } = {},
) {
  const defaultPageSize = options.defaultPageSize ?? 10;
  return {
    page: state.pageIndex > 0 ? state.pageIndex + 1 : undefined,
    size: state.pageSize !== defaultPageSize ? state.pageSize : undefined,
    sort:
      state.sorting.length > 0
        ? state.sorting.map((s) => (s.desc ? `-${s.id}` : s.id)).join(",")
        : undefined,
    q: state.filter !== "" ? state.filter : undefined,
  };
}

/**
 * 把路由的 search 接成 `DataTableListStore`。`setSearch` 收到的是要合并进 URL 的四个键，
 * 页面负责交给路由，这样本文件不依赖任何路由库：
 *
 * @example
 * ```tsx
 * export const Route = createFileRoute("/books/")({ validateSearch: parseListSearch, ... });
 *
 * const search = Route.useSearch();
 * const navigate = Route.useNavigate();
 * const t = useAbpTable(bookService, {
 *   columns,
 *   list: searchListStore(search, (patch) =>
 *     navigate({ search: (prev) => ({ ...prev, ...patch }), replace: true }),
 *   ),
 * });
 * ```
 *
 * 用 `replace` 而不是 push：翻页、排序不该各占一条历史记录，否则「返回」要按很多次才出得去。
 */
export function searchListStore(
  search: ListSearch,
  setSearch: (patch: ReturnType<typeof listStateToSearch>) => unknown,
  options: { defaultPageSize?: number } = {},
): DataTableListStore {
  return {
    value: listStateFromSearch(search),
    onChange: (next) => {
      void setSearch(listStateToSearch(next, options));
    },
  };
}

import { type Localize, useLocalization } from "@jcoder-stack/abp-react/react";
import {
  type ColumnVisibilityState,
  functionalUpdate,
  type RowData,
  Subscribe,
  type TableOptions,
  tableFeatures,
  type Updater,
  useTable,
} from "@tanstack/react-table";
import {
  createElement,
  type MouseEvent,
  type ReactNode,
  useCallback,
  useEffect,
  useMemo,
  useRef,
} from "react";
import { devWarn } from "@/components/data-table/dev-warn";
import {
  baseFeatureMap,
  type ExtraFeatureMap,
  features,
  type NoExtraFeatures,
  type TableColumnDef,
  type TableFeaturesWith,
  type TableInstance,
} from "@/components/data-table/table-core";
import {
  type DataTableState,
  useDataTableState,
} from "@/components/data-table/use-data-table-state";
import { Checkbox } from "@/components/ui/checkbox";

type SelectionAtom = TableInstance<RowData>["atoms"]["rowSelection"];
type SelectionState = ReturnType<SelectionAtom["get"]>;

/** `Subscribe` 的「单一 source + selector」那条重载对应的 props 形状。
 *  本文件是 .ts（文件名进了 registry 清单），写不了 JSX，只能 createElement；而
 *  createElement 会把重载塌成最后一条（全 store，不收 source），显式给出 props 才选得对。 */
interface SelectionSubscribeProps<TSelected> {
  source: SelectionAtom;
  selector: (state: SelectionState) => TSelected;
  children: (selected: TSelected) => ReactNode;
}

/** 同上，对应「单一 source、无 selector」那条重载：整片选中映射按浅比较驱动重渲染。 */
interface SelectionIdentitySubscribeProps {
  source: SelectionAtom;
  selector?: undefined;
  children: (state: SelectionState) => ReactNode;
}

/** 页内选择列：表头全选（含 indeterminate），行内单选；checked→事件由调用方 handler 消费 `event.target.checked`。
 *
 *  两个复选框都包在 `Subscribe` 里而不是渲染期直接读：宿主的 `useTable` selector 已把
 *  rowSelection 摘出订阅，勾选不再重渲染 DataTable，渲染期读到的是永远停在初始态的快照。
 *  用独立导出的 `Subscribe` 而非 `table.Subscribe`——列的 header/cell 上下文给的是核心
 *  `Table`，`Subscribe` 只挂在 `useTable` 另行 memo 出的返回对象上，这里类型上拿不到。
 *  本文件统一用它（含下方的 `SelectedCount`）：`table.Subscribe` 只是同一组件补了个默认
 *  source，我们每处都显式给 source，同名两份反而只会在阅读时混淆。
 *
 *  cell 这份订阅与 `data-table.tsx` 的 `DataTableRow` 那份在当前组合下是重叠的——整行已被
 *  包在同样的订阅里，删掉这一份测试也全绿。重叠是有意的：本列定义要能独立成立，契约不该是
 *  「只有被 `DataTableRow` 包着才会刷新」，而 `UseDataTableOptions.features` 的 TSDoc 正教着
 *  下游去改 `data-table.tsx` 的表体。代价只是每行多一个订阅。 */
function selectionColumn<TData extends RowData>(
  L: Localize,
  onInput: () => void,
): TableColumnDef<TData> {
  return {
    id: "select",
    enableSorting: false,
    // 组件注入的列不进 Columns 菜单：藏掉它只会让「已选 N 项」无从取消，且菜单里会出现无标签项
    enableHiding: false,
    meta: { className: "w-10" },
    header: ({ table }) =>
      createElement<SelectionIdentitySubscribeProps>(Subscribe, {
        source: table.atoms.rowSelection,
        // 整片订阅而非投影：全选框的三态还取决于当前页在场哪些行，selector 只拿得到选中映射，
        // 算不出来；三态在回调里现算，那两个 getter 都直接读原子，读到的是最新值。
        // biome-ignore lint/correctness/noChildrenProp: Subscribe 的 children 是 render prop，createElement 的可变子参数只收 ReactNode，塞不进去
        children: () =>
          createElement(Checkbox, {
            checked: table.getIsAllPageRowsSelected()
              ? true
              : table.getIsSomePageRowsSelected()
                ? "indeterminate"
                : false,
            onCheckedChange: (value: boolean | "indeterminate") => {
              onInput();
              table.getToggleAllPageRowsSelectedHandler()({ target: { checked: value === true } });
            },
            "aria-label": L("Table:SelectAll"),
            // 半选只隐藏对勾，保留 indeterminate。对勾表示「全选」，拿它表示「部分」会误导；
            // aria-checked="mixed" 得留着，否则读屏会把「已选 2 行」播报成「未选中」。
            // 选了几行由紧邻上方的批量条给出。
            // tree 块的 TriStateCheckbox 半选画横线，跟这里不一样，别当不一致来「修」：
            // 那边把「部分授予」误读成「全部授予」是授权问题，这里只影响感知，不值得为它加依赖。
            className: "data-[state=indeterminate]:[&_[data-slot=checkbox-indicator]]:opacity-0",
          }),
      }),
    cell: ({ row, table }) =>
      createElement<SelectionSubscribeProps<boolean>>(Subscribe, {
        source: table.atoms.rowSelection,
        selector: (s) => Boolean(s?.[row.id]),
        // biome-ignore lint/correctness/noChildrenProp: 同上
        children: (selected) =>
          createElement(Checkbox, {
            checked: selected,
            onCheckedChange: (value: boolean | "indeterminate") => {
              onInput();
              row.getToggleSelectedHandler()({ target: { checked: value === true } });
            },
            onClick: (e: MouseEvent) => e.stopPropagation(),
            "aria-label": L("Table:SelectRow"),
          }),
      }),
  };
}

export interface UseDataTableOptions<
  TData extends RowData,
  TExtra extends ExtraFeatureMap = NoExtraFeatures,
> {
  /** 分页/排序/选择状态机；省略则内部自建（纯客户端数据场景，不需要与外部查询参数联动）。 */
  state?: DataTableState;
  /** 列定义，引用必须稳定。`useTable` 每渲染收到新数组会重建列模型，上层所有以 columns
   *  为依赖的 memo 也跟着失效。`header` 里要用 `L()` 就包一层 `useMemo(() => [...], [L])`，
   *  `L` 的引用是稳的，等价于永久 memo。违反时 DEV 期会告警。
   *
   *  追加了特性时两种写法都收：按 `TableColumnDef<TData, TExtra>` 写才能在 cell 里点出追加
   *  特性的行 API；只用基础 API 的旧列定义原样传入也行，不必为追加一个特性改写全部列。 */
  columns: NoInfer<TableColumnDef<TData, TExtra>[] | TableColumnDef<TData>[]>;
  data: TData[];
  pageCount?: number;
  rowCount?: number;
  selectable?: boolean;
  /** 用户亲手动了勾选框（表头或行内）时调用，在选中态写入之前。程序性的写入（翻页清空、
   *  `keepSelected`）不触发，所以它能把「用户改了选择」和「表自己调整了选择」分开。不需要引用稳定。 */
  onSelectionInput?: () => void;
  getRowId?: (row: TData, index: number) => string;
  /** 追加 TanStack 特性（含 `expandedRowModel` 这类 row model 槽），与基础集加法合并；
   *  它的类型即 `TExtra`，返回的 `dt.table`、`tableOptions` 随之带上追加特性的 API。
   *  引用必须稳定，建议用模块级常量：`useTable` 只在挂载时构造一次表实例，特性在那时注册完，
   *  之后再变会被忽略，也不会触发重建。
   *
   *  注册不等于渲染。注册只让特性的状态和 API 可用，画面靠列定义（cell 里用行 API）与
   *  `DataTable` 的行级插槽（`renderSubRow`）补上，不必改本块源码；`data-table-expanding`
   *  块就是照这条路实现的，可作范例。 */
  features?: TExtra;
  /** 透传给 useTable，展开在受管选项之后，同名键调用方赢，接管即自负。
   *  `features` 走专门的 prop，类型层禁止在这里传，免得打破加法合并的不变式。 */
  tableOptions?: NoInfer<Omit<Partial<TableOptions<TableFeaturesWith<TExtra>, TData>>, "features">>;
}

export interface DataTableInstance<
  TData extends RowData,
  TExtra extends ExtraFeatureMap = NoExtraFeatures,
> {
  table: TableInstance<TData, TExtra>;
  state: DataTableState;
  /** 当前选中行，调用时取值。选中态归表所有，页面不再随它重渲染，
   *  渲染期读到的快照会陈旧——只在动作处理函数里调它。 */
  getSelectedRows: () => TData[];
  clearSelection: () => void;
  /** 只保留这些行选中；部分失败时回填用。ids 是 `getRowId` 产出的行 ID。 */
  keepSelected: (ids: string[]) => void;
  /** 订阅选中态并把计数交给 children，用于渲染期显示计数。 */
  SelectedCount: (props: { children: (count: number) => ReactNode }) => ReactNode;
  pageCount: number;
  rowCount?: number;
  selectable: boolean;
}

/** 建 TanStack 表实例：合成勾选列、注册特性、绑定状态机、剪枝离场行的选中态。 */
export function useDataTable<
  TData extends RowData,
  TExtra extends ExtraFeatureMap = NoExtraFeatures,
>(options: UseDataTableOptions<TData, TExtra>): DataTableInstance<TData, TExtra> {
  // 内部一律按基础特性集操作，出口再放宽回 TExtra；理由见 table-core 的 `asBaseTable`。
  const opts = options as unknown as UseDataTableOptions<TData>;
  const L = useLocalization();
  // hooks 必须无条件调用：外部没给 state 也要建内部状态机，只是外部给了就不用
  const internalState = useDataTableState();
  const state = opts.state ?? internalState;

  const onSelectionInputRef = useRef(opts.onSelectionInput);
  onSelectionInputRef.current = opts.onSelectionInput;
  const columns = useMemo(
    () =>
      opts.selectable
        ? [selectionColumn<TData>(L, () => onSelectionInputRef.current?.()), ...opts.columns]
        : opts.columns,
    [opts.selectable, opts.columns, L],
  );
  const tableFeatureSet = useMemo(
    () => (opts.features ? tableFeatures({ ...baseFeatureMap, ...opts.features }) : features),
    [opts.features],
  );
  // 引用比较：features 的契约本就是「必须引用稳定」，引用变本身即误用，无需比较内容。
  const mountedFeatures = useRef(opts.features);
  useEffect(() => {
    if (mountedFeatures.current !== opts.features) {
      devWarn(
        "data-table:features-changed",
        "data-table: features prop 在挂载后改变了引用，新值已被忽略。useTable 只在挂载时构造" +
          "表实例、特性注册在构造时完成，挂载后的变更不会触发重建。请把它提成模块级常量。",
      );
    }
  }, [opts.features]);
  const prevColumns = useRef(opts.columns);
  const columnsChurn = useRef(0);
  useEffect(() => {
    if (!import.meta.env.DEV) return;
    columnsChurn.current = prevColumns.current === opts.columns ? 0 : columnsChurn.current + 1;
    prevColumns.current = opts.columns;
    if (columnsChurn.current >= 3) {
      devWarn(
        "data-table:columns-churn",
        "data-table: columns 每次渲染都是新数组，表实例的列模型与上层所有以 columns 为依赖的 " +
          "memo 会全部失效。用 useMemo(() => [...], [L]) 包住——useLocalization 的 L 引用稳定，" +
          "等价于永久 memo。",
      );
    }
  });
  const { setColumnVisibility } = state;
  const table = useTable(
    {
      features: tableFeatureSet,
      data: opts.data,
      columns,
      pageCount: opts.pageCount ?? 1,
      onPaginationChange: state.onPaginationChange,
      onSortingChange: state.onSortingChange,
      // 接了偏好存储时列显隐改由它持有。没存过值之前 state 里不带这一片，表实例仍按
      // 自己的初始状态（含调用方 `tableOptions.initialState` 给的默认隐藏列）显示；
      // 用户第一次动列时以表的当前值为基准写进存储，此后才转为受控。
      ...(setColumnVisibility && {
        onColumnVisibilityChange: (updater: Updater<ColumnVisibilityState>) =>
          setColumnVisibility(functionalUpdate(updater, table.atoms.columnVisibility.get())),
      }),
      enableRowSelection: opts.selectable ?? false,
      manualPagination: true,
      manualSorting: true,
      getRowId: opts.getRowId,
      ...opts.tableOptions,
      // 一层合并而非整体覆盖：tableOptions.state 只能按键覆盖/追加受管切片，
      // 不会把 pagination/sorting 整体挤掉造成组件渲染与表状态失步。
      // rowSelection 刻意缺席：那一片归表自己所有，见下方的 SelectedCount / getSelectedRows。
      state: {
        pagination: state.pagination,
        sorting: state.sorting,
        ...(state.columnVisibility && { columnVisibility: state.columnVisibility }),
        ...opts.tableOptions?.state,
      },
    },
    // 省略 selector 等于订阅全部切片，勾一个复选框就要重渲染整张表，成本随行数放大。
    // 摘掉 rowSelection 之后它由表头/行内/SelectedCount 各自定点订阅，宿主不再为它重渲染。
    // 用排除法而非列举需要的切片：features 是加法合并的，调用方追加特性带来的切片
    // （如 columnFilteringFeature 的 columnFilters）不在列举里就永远不触发重渲染，
    // 他们的筛选 UI 会静默失灵。返回新对象不会每渲染都重渲染——结果走浅比较。
    (tableState) => {
      const { rowSelection: _rowSelection, ...rest } = tableState;
      return rest;
    },
  );

  // 全部取自表实例但绕开 table 本身：useTable 每渲染都返回一份新的表对象（options 是渲染期
  // 新建的），拿 table 当依赖等于没 memo；而这些方法与原子建表时就定下，引用恒定。
  const { getCoreRowModel, getSelectedRowModel, resetRowSelection, setRowSelection } = table;
  const rowSelectionAtom = table.atoms.rowSelection;

  // 翻页/排序/换查询语境会换一批在场行，页内选择随之作废。这条不变式原先在状态机里，
  // 但那里拿不到表实例；所有权交给表之后只能在这里承接。
  // scopeEpoch 不可省：搜索与查询面板提交都走 resetPaging，用户本来就在第 1 页时
  // 分页与排序可以一起纹丝不动，只比这两样会让选中态跨查询语境残留。
  const { pageIndex, pageSize } = state.pagination;
  const scopeKey = `${pageIndex}:${pageSize}:${state.scopeEpoch}:${state.sorting.map((s) => `${s.id}:${s.desc}`).join(",")}`;
  const lastScope = useRef(scopeKey);
  useEffect(() => {
    // 挂载帧不算「翻页/排序变了」：不跳过就会在首次 effect 里清一次选择，把挂载前经
    // keepSelected 回填的结果立刻抹掉。用「上次作用域」而非「是不是首帧」记这件事，
    // 顺带扛住依赖抖动——resetRowSelection 每次写入的都是新对象，多跑一次就再触发一次
    // 渲染，真被无谓地重跑就是死循环。
    if (lastScope.current === scopeKey) return;
    lastScope.current = scopeKey;
    resetRowSelection();
  }, [scopeKey, resetRowSelection]);

  // 行离场（删除后 refetch、外部 invalidate）时剔除对应的选中 id。选中数有两个口径：
  // 批量条显隐看 state 键数，内容看在场行数，不剪枝就会分裂出「已选 0 项」的幽灵批量条。
  // 剪枝只看当前 data，跟 keepPreviousData 天然兼容，fetching 期间旧行还在场，不会误清。
  // biome-ignore lint/correctness/useExhaustiveDependencies: opts.data 是触发源而非读取对象——体内经 getCoreRowModel() 读到同一份数据，而那个方法引用恒定，没有它 effect 不会随换数据重跑
  useEffect(() => {
    // 从原子读而非从渲染期快照读：上面那条清空 effect 先跑，翻页同时换数据时快照已经过期。
    // table.atoms 的键是必需的（Atoms<TFeatures> 用了 -?），rowSelectionFeature 已在
    // baseFeatureMap 里注册，所以这里不需要可选链；?? {} 只兜住切片值本身的 undefined。
    const current = rowSelectionAtom.get() ?? {};
    const selected = Object.keys(current);
    if (selected.length === 0) return;
    // 取核心行模型的 flatRows 而不是 opts.data 的顶层：追加 `getSubRows` 的树表里，勾中的
    // 子行不在顶层，只看顶层会在每次 refetch 时把它们误判离场清掉。
    const present = new Set(getCoreRowModel().flatRows.map((row) => row.id));
    if (selected.every((id) => present.has(id))) return;
    setRowSelection(Object.fromEntries(Object.entries(current).filter(([id]) => present.has(id))));
  }, [opts.data, getCoreRowModel, rowSelectionAtom, setRowSelection]);

  const getSelectedRows = useCallback(
    () => getSelectedRowModel().rows.map((r) => r.original),
    [getSelectedRowModel],
  );
  const clearSelection = useCallback(() => resetRowSelection(), [resetRowSelection]);
  const keepSelected = useCallback(
    (ids: string[]) => setRowSelection(Object.fromEntries(ids.map((id) => [id, true]))),
    [setRowSelection],
  );

  /** 订阅选中态并把计数交给 children。用它而不是在渲染期读快照——
   *  所有权在表里之后，页面不再因选中变化重渲染，快照会陈旧。
   *  组件身份必须稳定，否则每渲染都是一个新组件类型，React 会把它整棵子树卸载重挂
   *  （工具条要把搜索框放进它的 children，重挂就丢焦点和已输入内容）。 */
  const SelectedCount = useMemo(
    () =>
      function SelectedCount(p: { children: (count: number) => ReactNode }) {
        return createElement<SelectionSubscribeProps<number>>(Subscribe, {
          source: rowSelectionAtom,
          selector: (s) => Object.keys(s ?? {}).length,
          // biome-ignore lint/correctness/noChildrenProp: Subscribe 的 children 是 render prop（收计数返回节点），createElement 的可变子参数只收 ReactNode，塞不进去
          children: p.children,
        });
      },
    [rowSelectionAtom],
  );

  return {
    table: table as unknown as TableInstance<TData, TExtra>,
    state,
    getSelectedRows,
    clearSelection,
    keepSelected,
    SelectedCount,
    pageCount: opts.pageCount ?? 1,
    rowCount: opts.rowCount,
    selectable: opts.selectable ?? false,
  };
}

