import { cn } from "@/lib/utils";

const DEFAULT_SKELETON_ROWS = 5;

/** 骨架条的宽度轮换：同一列上下等宽、相邻列不等宽，读起来像一张表而不是一摞横条。 */
const SKELETON_WIDTHS = ["w-3/4", "w-1/2", "w-2/3"] as const;

function alignClass(align?: "left" | "right" | "center") {
  // 右对齐即数字列（DESIGN.md「Tables」）：一并给等宽数字，否则 Inter 的比例数字宽窄不一，
  // 同列上下对不齐、跨组件（分页/页码）看着像换了字体。
  if (align === "right") return "text-right tabular-nums";
  if (align === "center") return "text-center";
  return "";
}

function justifyClass(align?: "left" | "right" | "center") {
  if (align === "right") return "justify-end";
  if (align === "center") return "justify-center";
  return "justify-start";
}

/** 固定单元格的共同部分。底色必须不透明，否则滚过去的列会透上来；而行的悬停色和表头色都是
 *  半透明的，所以拆成两层：单元格自己铺 `bg-card`，状态色画在 `::before` 上叠在它之上、
 *  内容之下（sticky 自成层叠上下文，`-z-10` 出不去）。 */
const STICKY_CELL = "sticky z-10 bg-card before:absolute before:inset-0 before:-z-10";
/** 固定区右缘的投影，只在横向滚动过之后出现：没滚动时固定列与其余列并排，没有东西被它盖住，
 *  常驻的边线只是多一条竖线。画在 `::after` 上并伸到单元格右侧之外，盖在滚过去的内容上。 */
const STICKY_EDGE =
  "after:pointer-events-none after:absolute after:inset-y-0 after:left-full after:w-2 after:bg-linear-to-r after:from-border after:to-transparent after:opacity-0 after:transition-opacity group-data-[scrolled]/scroll:after:opacity-100";
/** 主列紧贴勾选列之后。勾选列声明的是 `w-10`，但自动布局的表格会把它压到内容宽度，
 *  所以固定时用 `min-w-10` 钉死，否则两者之间会露出一条缝，滚过去的列从缝里透出来。 */
const STICKY_SELECT = "left-0 min-w-10";
const STICKY_AFTER_SELECT = "left-10";

interface DataTableRowProps<TData extends RowData>
  extends Pick<DataTableProps<TData>, "rowProps" | "onRowClick"> {
  row: Row<TableFeatures, TData>;
  selectionAtom: TableInstance<TData>["atoms"]["rowSelection"];
  stickyClassOf: (columnId: string) => string | undefined;
}

/** 表体的一行。整行包在自己那一行的选中订阅里：`data-state` 是 `<TableRow>` 上的属性，
 *  而宿主的 `useTable` selector 已把 rowSelection 摘出去、不再因勾选重渲染，只有把整行
 *  放进订阅，选中底色才跟得上。刻意不加 `React.memo`：订阅本就没有比较面，加了反而把
 *  `rowProps` / `onRowClick` 的「不需要引用稳定」契约拖下水。
 *
 *  这份订阅与选择列 cell 里那份（见 `use-data-table.ts` 的 `selectionColumn`）在当前组合下
 *  是重叠的——本组件把整行连同各 cell 一起包住，删掉任意一份，测试都还全绿。重叠是有意的，
 *  两份都不能删：本组件负责 `<tr>` 的 `data-state`，是列定义碰不到的；`selectionColumn`
 *  则要能独立成立，它的契约不该是「只有被 DataTableRow 包着才会刷新」——`UseDataTableOptions`
 *  的 `features` TSDoc 正教着下游改本文件的表体。 */
function DataTableRow<TData extends RowData>(props: DataTableRowProps<TData>) {
  const { row, selectionAtom, rowProps, onRowClick, stickyClassOf } = props;
  return (
    <Subscribe source={selectionAtom} selector={(s) => Boolean(s?.[row.id])}>
      {(selected) => (
        <TableRow
          data-state={selected ? "selected" : undefined}
          className={cn(
            "group hover:bg-muted/50 data-[state=selected]:bg-row-selected",
            onRowClick &&
              "cursor-pointer focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-ring",
            rowProps?.(row.original)?.className,
          )}
          tabIndex={onRowClick ? 0 : undefined}
          onClick={() => onRowClick?.(row.original)}
          onKeyDown={
            onRowClick &&
            ((e) => {
              if (e.key === "Enter" || e.key === " ") {
                // 两个都要 preventDefault。Space 默认滚动页面；Enter 会在本次按键继续合成
                // 一次 click，落到激活后新获得焦点的元素上（详情抽屉里的「编辑」按钮），
                // 键盘激活就越过详情态直接进了编辑态。
                // 行操作菜单已在自己的 onKeyDown 里 stopPropagation，不会误触发行激活。
                e.preventDefault();
                onRowClick(row.original);
              }
            })
          }
        >
          {row.getVisibleCells().map((cell) => (
            <TableCell
              key={cell.id}
              className={cn(
                alignClass(cell.column.columnDef.meta?.align),
                cell.column.columnDef.meta?.className,
                stickyClassOf(cell.column.id) &&
                  cn(
                    stickyClassOf(cell.column.id),
                    "group-hover:before:bg-muted/50 group-data-[state=selected]:before:bg-row-selected",
                  ),
              )}
            >
              {flexRender(cell.column.columnDef.cell, cell.getContext())}
            </TableCell>
          ))}
        </TableRow>
      )}
    </Subscribe>
  );
}

export interface DataTableProps<
  TData extends RowData,
  TExtra extends ExtraFeatureMap = NoExtraFeatures,
> {
  /** 由 `useDataTable` 构造的表实例；列/数据/分页/排序/选择全部经它接入。 */
  table: DataTableInstance<TData, TExtra>;
  /** 无数据可显示、正在首次取数 → 渲染骨架行。 */
  loading?: boolean;
  /** 已有数据在位、正在取新数据 → 表体降透明度。与 `loading` 互斥，react-query 下传
   *  `isFetching && !isPending`。表头不降透明度，排序仍可点，它也是用户定位刚点了什么的锚点。 */
  fetching?: boolean;
  /** 在位的数据是上一次成功的结果、最近一次刷新失败了 → 表体降到一半透明度。它比 `fetching`
   *  更淡：那边是「马上就新」，这边是「不知道还对不对」。提示文案与重试由调用方另行渲染。 */
  stale?: boolean;
  /** 空状态。缺省是 `L("Table:Empty")` 的居中单行。传了只替换 `<td>` 内的内容，外层
   *  `<tr><td colSpan>` 仍由组件提供，不用自己算 colSpan。注意那个 `<td>` 带着
   *  `h-24 text-center text-muted-foreground`，插图 + 标题 + 按钮这类空状态会被强制居中、
   *  标题被染成 muted 色，要退出得自己在内容上加覆盖类。 */
  empty?: ReactNode;
  /** 首次取数失败、没有任何数据可显示时的表体内容。给了它，表体整块换成这段内容（外层
   *  `<tr><td colSpan>` 由组件提供），表头留在原位，页脚不渲染——出错时总数和页数都不可信。
   *  已有数据在位的刷新失败不该走这里：那时旧数据仍有效，调用方应保留表体，另行提示。 */
  error?: ReactNode;
  /** 骨架行数；缺省 5。后台里不满一页的小表很常见，跟随每页条数会让它们从十行骨架塌成
   *  两三行数据。通常能填满一页的大表传 `"pageSize"`，跟随当前 `pagination.pageSize`。 */
  skeletonRows?: number | "pageSize";
  /** 行级属性，只开 `className`。事件走 `onRowClick`，万能透传会让调用方覆盖掉
   *  `key`/`data-state` 这些组件自管的东西。收 `row.original` 而不是 `Row`，要判断的是业务
   *  状态而非表格行状态。不需要引用稳定，它不进任何 memo 依赖，只在渲染时调用。
   *
   *  要覆盖悬停态或选中态得自带对应变体，例如
   *  `{ className: "bg-red-50 hover:bg-red-50 data-[state=selected]:bg-red-50" }`。
   *  只给 `bg-red-50` 的话，组件自带的 `hover:bg-muted/50` 和
   *  `data-[state=selected]:bg-row-selected` 修饰符不同，`cn` 不去重，
   *  悬停和选中时又特异性更高，会把你的颜色盖回去。 */
  rowProps?: (row: TData) => { className?: string };
  onRowClick?: (row: TData) => void;
  /** 行后追加一行通栏内容（折叠详情、行内子表），返回 `null`/`undefined`/`false` 即不追加。外层
   *  `<tr><td colSpan>` 由组件提供，colSpan 跟随可见列数。收 `Row` 而不是 `row.original`：
   *  要据以判断的是 `row.getIsExpanded()` 这类表格行状态，追加了 `rowExpandingFeature` 时
   *  它在类型上可见。与 `rowProps` 一样不需要引用稳定。
   *
   *  通栏行不吃 `onRowClick`、没有悬停底色，也不参与选中；`<td>` 无内边距，留白由内容自定。 */
  renderSubRow?: (row: TableRowInstance<TData, TExtra>) => ReactNode;
  /** 接管整个页脚区：总条数文字和分页器。缺省渲染内建页脚。做「加载更多」或无限滚动的
   *  调用方本就不要页码，拆开接管只会让他们分别关两个开关；要保留哪部分自己从 ctx 拼，
   *  分页动作走 `ctx.table.nextPage()` 这些。每页条数不在页脚，见 `DataTableViewMenu`。 */
  footer?: (ctx: {
    table: TableInstance<TData, TExtra>;
    pagination: PaginationState;
    pageCount: number;
    rowCount?: number;
  }) => ReactNode;
  /** 工具栏等散件，渲染在卡片内部、表格上方，顺序即摆放顺序。 */
  children?: ReactNode;
}

/** 服务端分页的通用表格。实例由 `useDataTable` 构造后传入，本组件只管表现层：
 *  骨架、空态、报错态、表头表体和内建页脚。行操作列由调用方当普通 column 传进来。 */
export function DataTable<TData extends RowData, TExtra extends ExtraFeatureMap = NoExtraFeatures>(
  props: DataTableProps<TData, TExtra>,
) {
  const L = useLocalization();
  const tableId = useId();
  const { table: dt } = props;
  const table = asBaseTable(dt.table);
  const skeletonCount =
    props.skeletonRows === "pageSize"
      ? dt.state.pagination.pageSize
      : (props.skeletonRows ?? DEFAULT_SKELETON_ROWS);
  const hasError = props.error != null && props.error !== false;

  const visibleColumns = table.getVisibleLeafColumns();
  const stickyColumnId = visibleColumns.find((column) => column.columnDef.meta?.sticky)?.id;
  const hasSelectColumn = visibleColumns.some((column) => column.id === "select");
  // 有固定主列时勾选列一起固定：它在主列左边，不固定就会从主列底下滑走，行也就没法勾了。
  const stickyClassOf = (columnId: string) => {
    if (stickyColumnId === undefined) return undefined;
    if (columnId === "select") return cn(STICKY_CELL, STICKY_SELECT);
    if (columnId === stickyColumnId) {
      return cn(STICKY_CELL, STICKY_EDGE, hasSelectColumn ? STICKY_AFTER_SELECT : "left-0");
    }
    return undefined;
  };

  const footerContent = props.footer ? (
    props.footer({
      table: dt.table,
      pagination: dt.state.pagination,
      pageCount: dt.pageCount,
      rowCount: dt.rowCount,
    })
  ) : (
    <DataTableFooter
      table={table}
      pagination={dt.state.pagination}
      pageCount={dt.pageCount}
      rowCount={dt.rowCount}
    />
  );

  return (
    <div className="overflow-hidden rounded-md border bg-card">
      {props.children}
      {/* 滚动的是原语内部那层容器，这里拿不到它的 ref；scroll 不冒泡但会经过捕获阶段。
          直接写属性而不进 state：整张表不必为「滚没滚过」重渲染，React 也不管这个属性。 */}
      <div
        className="group/scroll"
        onScrollCapture={(event) => {
          if (!(event.target instanceof HTMLElement)) return;
          if (event.target.dataset.slot !== "table-container") return;
          event.currentTarget.toggleAttribute("data-scrolled", event.target.scrollLeft > 0);
        }}
      >
        <Table
          // 行高是声明出来的，不是内容撑出来的：此前两档都靠单元格内距，于是同一档里
          // "有行尾菜单的行"比"纯文本行"高 12px，密度实际由那个按钮决定。
          className={cn(dt.state.density === "compact" ? "[&_td]:h-8" : "[&_td]:h-10")}
          aria-busy={props.loading || props.fetching ? true : undefined}
        >
          <TableHeader>
            {table.getHeaderGroups().map((headerGroup) => (
              <TableRow key={headerGroup.id}>
                {headerGroup.headers.map((header) => {
                  const showSortIndex =
                    table.state.sorting.length > 1 && Boolean(header.column.getIsSorted());
                  const sortPriorityId = `${tableId}-sortpri-${header.id}`;
                  return (
                    <TableHead
                      key={header.id}
                      aria-sort={
                        header.column.getIsSorted() === "asc"
                          ? "ascending"
                          : header.column.getIsSorted() === "desc"
                            ? "descending"
                            : header.column.getCanSort()
                              ? "none"
                              : undefined
                      }
                      className={cn(
                        // label-caps：正字距的大写小字把表头标记为"分类"而非内容，
                        // 是这套系统里唯一用正字距的地方（DESIGN.md「Typography」）。
                        "bg-muted/50 text-xs font-medium uppercase tracking-wide text-muted-foreground",
                        alignClass(header.column.columnDef.meta?.align),
                        header.column.columnDef.meta?.className,
                        stickyClassOf(header.column.id) &&
                          cn(stickyClassOf(header.column.id), "before:bg-muted/50"),
                      )}
                    >
                      {header.isPlaceholder ? null : header.column.getCanSort() ? (
                        <button
                          type="button"
                          onClick={header.column.getToggleSortingHandler()}
                          aria-describedby={showSortIndex ? sortPriorityId : undefined}
                          className={cn(
                            "inline-flex w-full items-center gap-1.5 select-none hover:text-foreground",
                            "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring",
                            justifyClass(header.column.columnDef.meta?.align),
                          )}
                        >
                          {flexRender(header.column.columnDef.header, header.getContext())}
                          {header.column.getIsSorted() === "asc" ? (
                            <ChevronUp className="size-3 text-primary" />
                          ) : header.column.getIsSorted() === "desc" ? (
                            <ChevronDown className="size-3 text-primary" />
                          ) : (
                            <ChevronsUpDown className="size-3 opacity-50" />
                          )}
                          {showSortIndex && (
                            // 优先级本就不可用 ARIA 表达（aria-sort 只有方向），裸数字留在可访问名里
                            // 会污染读屏播报与语音控制的匹配目标（按钮会变成「Name1」而非「Name」）。
                            <span
                              aria-hidden="true"
                              className="text-2xs font-normal tabular-nums text-muted-foreground"
                            >
                              {header.column.getSortIndex() + 1}
                            </span>
                          )}
                        </button>
                      ) : (
                        flexRender(header.column.columnDef.header, header.getContext())
                      )}
                      {showSortIndex && (
                        // 描述得放 button 外面，进 button 会并入可访问名、污染语音控制的匹配目标，
                        // 而 aria-describedby 只影响描述不影响名称。但 th 自己也是 "name from
                        // content" 的角色，不加 aria-hidden 这段文字照样会并进表头的可访问名。
                        // aria-hidden 把它逐出常规内容遍历，aria-describedby 的直接引用不受影响，
                        // 读屏仍读得到。
                        <span id={sortPriorityId} aria-hidden="true" className="sr-only">
                          {L("Table:SortPriority", header.column.getSortIndex() + 1)}
                        </span>
                      )}
                    </TableHead>
                  );
                })}
              </TableRow>
            ))}
          </TableHeader>
          <TableBody
            className={cn(
              // delay-100 吃掉快请求的闪烁，100ms 内返回的几乎看不出变化，且不用 JS 定时器。
              // 没加 pointer-events-none：它只挡鼠标不挡键盘，两类用户会拿到不同能力；
              // keepPreviousData 期间在位的又正是上一次的有效数据，点它并不危险（行操作打的是
              // id，行真没了服务端会 404）。「正在刷新」靠降透明度 + aria-busy 表达，不禁用交互。
              props.fetching && "opacity-60 transition-opacity duration-150 delay-100",
              props.stale && "opacity-50",
            )}
          >
            {hasError ? (
              <TableRow className="hover:bg-transparent">
                <TableCell
                  colSpan={table.getVisibleLeafColumns().length}
                  className="h-24 text-center"
                >
                  {props.error}
                </TableCell>
              </TableRow>
            ) : props.loading ? (
              Array.from({ length: skeletonCount }, (_, i) => (
                // biome-ignore lint/suspicious/noArrayIndexKey: 骨架占位行数固定且从不重排
                <TableRow key={`skeleton-${i}`} className="hover:bg-transparent">
                  {table.getVisibleLeafColumns().map((column, columnIndex) => {
                    const meta = column.columnDef.meta;
                    return (
                      // 每列一格而不是整行一条：列宽在骨架期就由表头和 meta.className 定下，
                      // 数据到达时列不横向跳动。
                      <TableCell
                        key={column.id}
                        className={cn(
                          alignClass(meta?.align),
                          meta?.className,
                          stickyClassOf(column.id),
                        )}
                      >
                        <Skeleton
                          className={cn(
                            // 没有取值器的是展示列（勾选框、行操作），内容本就是个小图标位。
                            column.accessorFn
                              ? ["h-4", SKELETON_WIDTHS[columnIndex % SKELETON_WIDTHS.length]]
                              : "size-4",
                            meta?.align === "right" && "ml-auto",
                            meta?.align === "center" && "mx-auto",
                          )}
                        />
                      </TableCell>
                    );
                  })}
                </TableRow>
              ))
            ) : table.getRowModel().rows.length === 0 ? (
              <TableRow>
                <TableCell
                  colSpan={table.getVisibleLeafColumns().length}
                  className="h-24 text-center text-muted-foreground"
                >
                  {props.empty ?? L("Table:Empty")}
                </TableCell>
              </TableRow>
            ) : (
              table.getRowModel().rows.map((row) => {
                // 行对象运行时就是带着追加特性的那一个，这里只是把类型放宽回调用方声明的特性集。
                const subRow = props.renderSubRow?.(
                  row as unknown as TableRowInstance<TData, TExtra>,
                );
                return (
                  <Fragment key={row.id}>
                    <DataTableRow
                      row={row}
                      selectionAtom={table.atoms.rowSelection}
                      rowProps={props.rowProps}
                      onRowClick={props.onRowClick}
                      stickyClassOf={stickyClassOf}
                    />
                    {subRow != null && subRow !== false && (
                      <TableRow data-slot="data-table-sub-row" className="hover:bg-transparent">
                        <TableCell colSpan={table.getVisibleLeafColumns().length} className="p-0">
                          {subRow}
                        </TableCell>
                      </TableRow>
                    )}
                  </Fragment>
                );
              })
            )}
          </TableBody>
        </Table>
      </div>
      {/* footer 返回 falsy（无限滚动这类不要页脚的接管）时连外壳一起不渲染，
          否则卡片底部会留一条 1px 上边框加一段空白。 */}
      {footerContent && !hasError ? (
        <div className="border-t px-4 py-2">{footerContent}</div>
      ) : null}
    </div>
  );
}

import { useLocalization } from "@jcoder-stack/abp-react/react";
import type { PaginationState, RowData } from "@tanstack/react-table";
import { ChevronLeft, ChevronRight } from "lucide-react";
import type { ReactNode } from "react";
import type { TableInstance } from "@/components/data-table/table-core";
import {
  Pagination,
  PaginationContent,
  PaginationEllipsis,
  PaginationItem,
  PaginationLink,
} from "@/components/ui/pagination";
import { cn } from "@/lib/utils";

const PAGE_WINDOW_THRESHOLD = 7;

/**
 * 0-based 页码窗口：总页 ≤7 全显；否则**恒定 7 个槽位**，首页与末页占两端，中间五槽随当前页滑动。
 *
 * 槽位数必须恒定：数量随当前页变化时，翻一页整排页码就会左右平移，按钮跑到光标底下换了张脸，
 * 连点下一页看起来像在闪烁。宁可多显示一个省略号，也不让已经画出来的页码挪位置。
 */
export function getPageItems(pageIndex: number, pageCount: number): (number | "ellipsis")[] {
  const totalPages = Math.max(pageCount, 1);
  if (totalPages <= PAGE_WINDOW_THRESHOLD) {
    return Array.from({ length: totalPages }, (_, i) => i);
  }

  const last = totalPages - 1;
  const current = Math.min(Math.max(pageIndex, 0), last);

  if (current <= 3) return [0, 1, 2, 3, 4, "ellipsis", last];
  if (current >= last - 3) return [0, "ellipsis", last - 4, last - 3, last - 2, last - 1, last];
  return [0, "ellipsis", current - 1, current, current + 1, "ellipsis", last];
}

/** 内建页脚：总条数 + 分页器。每页条数是视图设置，在 `DataTableViewMenu` 里。
 *  与表体正交，单独成文件降低 fork 进入成本。 */
export function DataTableFooter<TData extends RowData>(props: {
  table: TableInstance<TData>;
  pagination: PaginationState;
  pageCount: number;
  rowCount?: number;
}): ReactNode {
  const L = useLocalization();
  const { table } = props;
  const canPrev = table.getCanPreviousPage();
  const canNext = table.getCanNextPage();
  const pageItems = getPageItems(props.pagination.pageIndex, props.pageCount);

  const prevItem = (
    <PaginationItem>
      <PaginationLink
        size="icon"
        className={cn("size-8", !canPrev && "pointer-events-none opacity-50")}
        aria-label={L("Table:Previous")}
        aria-disabled={!canPrev}
        href={canPrev ? "#" : undefined}
        onClick={(e) => {
          e.preventDefault();
          if (canPrev) table.previousPage();
        }}
      >
        <ChevronLeft />
      </PaginationLink>
    </PaginationItem>
  );

  const nextItem = (
    <PaginationItem>
      <PaginationLink
        size="icon"
        className={cn("size-8", !canNext && "pointer-events-none opacity-50")}
        aria-label={L("Table:Next")}
        aria-disabled={!canNext}
        href={canNext ? "#" : undefined}
        onClick={(e) => {
          e.preventDefault();
          if (canNext) table.nextPage();
        }}
      >
        <ChevronRight />
      </PaginationLink>
    </PaginationItem>
  );

  return (
    <div className="flex items-center justify-between gap-2">
      <div className="flex items-center gap-2 text-sm tabular-nums text-muted-foreground">
        {props.rowCount !== undefined && props.rowCount > 0 && (
          <span>{L("Table:Total", props.rowCount)}</span>
        )}
      </div>
      <div className="flex items-center gap-2">
        <span className="text-sm tabular-nums text-muted-foreground md:hidden">
          {L("Table:PageOf", props.pagination.pageIndex + 1, Math.max(props.pageCount, 1))}
        </span>
        <Pagination className="mx-0 w-auto md:hidden">
          <PaginationContent>
            {prevItem}
            {nextItem}
          </PaginationContent>
        </Pagination>
        <Pagination className="mx-0 hidden w-auto md:flex">
          <PaginationContent>
            {prevItem}
            {pageItems.map((item, i) =>
              item === "ellipsis" ? (
                // biome-ignore lint/suspicious/noArrayIndexKey: 省略号在窗口内位置固定，不参与重排
                <PaginationItem key={`ellipsis-${i}`}>
                  <PaginationEllipsis />
                </PaginationItem>
              ) : (
                <PaginationItem key={item}>
                  <PaginationLink
                    size="icon"
                    className={cn(
                      "size-8 tabular-nums",
                      // 当前页用中性填充，不用主色实心：它说的是「你在第几页」，不是「点这里」。
                      // 主色在一屏里只该有一处，那一处留给唯一的主按钮。
                      item === props.pagination.pageIndex &&
                        "border-input bg-secondary font-medium text-foreground hover:bg-secondary",
                    )}
                    isActive={item === props.pagination.pageIndex}
                    href="#"
                    onClick={(e) => {
                      e.preventDefault();
                      table.setPageIndex(item);
                    }}
                  >
                    {item + 1}
                  </PaginationLink>
                </PaginationItem>
              ),
            )}
            {nextItem}
          </PaginationContent>
        </Pagination>
      </div>
    </div>
  );
}

import { useLocalization } from "@jcoder-stack/abp-react/react";
import type { RowData } from "@tanstack/react-table";
import { Download, RefreshCw, Search, X } from "lucide-react";
import type { ReactNode } from "react";
import { useEffect, useRef, useState } from "react";
import type { ExtraFeatureMap, NoExtraFeatures } from "@/components/data-table/table-core";
import type { DataTableInstance } from "@/components/data-table/use-data-table";
import { Button } from "@/components/ui/button";
import {
  InputGroup,
  InputGroupAddon,
  InputGroupButton,
  InputGroupInput,
} from "@/components/ui/input-group";
import { Separator } from "@/components/ui/separator";
import { Tooltip, TooltipContent, TooltipTrigger } from "@/components/ui/tooltip";
import { cn } from "@/lib/utils";

/** 顶部条功能图标钮的共同外观：ghost 32px 方钮、静态色比正文更轻，hover 才提亮。 */
const UTILITY_ICON_CLASS = "size-8 text-muted-foreground";
const SEARCH_DEBOUNCE_MS = 400;

export interface DataTableToolbarProps<
  TData extends RowData,
  TExtra extends ExtraFeatureMap = NoExtraFeatures,
> {
  table: DataTableInstance<TData, TExtra>;
  /** 是否渲染内建搜索框；缺省 true。传了 `left` 时搜索框让位。 */
  search?: boolean;
  searchPlaceholder?: string;
  /** 左区自定义内容（如内联查询字段）；提供时替代内建搜索框。 */
  left?: ReactNode;
  /** 有选中行时替换整个左区的批量操作内容；缺席则选中时左区维持原样。 */
  bulk?: ReactNode;
  /** 刷新回调；缺席不渲染刷新按钮。`refreshing` 为 true 时图标旋转。 */
  onRefresh?: () => void;
  refreshing?: boolean;
  /** 导出插槽；缺席不渲染导出按钮，组件库不内置导出实现。 */
  onExport?: () => void;
  /** 页面级动作（如「新增」），primary 归它；与右侧功能图标组之间以竖线分隔。 */
  actions?: ReactNode;
  /** 功能区最前的散件（如查询面板开合钮），排在刷新之前，与「改表格外观」的那几个分开。 */
  utilityLeading?: ReactNode;
  /** trailing 区：视图设置（`DataTableViewMenu`）等散件，并入右侧功能图标组。 */
  children?: ReactNode;
}

/** 表格卡片顶部条：左区三态（自定义内容/搜索框 ⇄ 批量操作），右区恒定
 * （actions │ utilityLeading · 刷新 · 导出 · trailing）。Enter 立即提交搜索。 */
export function DataTableToolbar<
  TData extends RowData,
  TExtra extends ExtraFeatureMap = NoExtraFeatures,
>(props: DataTableToolbarProps<TData, TExtra>) {
  const L = useLocalization();
  const { state, SelectedCount } = props.table;
  const showSearch = props.search ?? true;

  // 即时值持有在组件本体而非条件子树：批量态会把整个左区换成 props.bulk，
  // 若把这份 state 放进搜索框所在的三元分支，批量态一进一出输入内容就丢了。
  // 以已提交的搜索值起步：深链预填时输入框要显示它，而不是空着却在筛选。
  const [searchInput, setSearchInput] = useState(state.params.filter);
  const timer = useRef<ReturnType<typeof setTimeout>>(undefined);
  const committedFilter = state.params.filter;
  // 本工具条自己提交过的最新值。已提交值与它不同，说明是外部改的（空态的「清除筛选」等），
  // 输入框要跟上；相同则是自己那次提交的回声，此时用户可能已经又敲了几个字，不能回写。
  const ownCommit = useRef(committedFilter);

  useEffect(() => () => clearTimeout(timer.current), []);

  useEffect(() => {
    if (committedFilter === ownCommit.current) return;
    ownCommit.current = committedFilter;
    clearTimeout(timer.current);
    setSearchInput(committedFilter);
  }, [committedFilter]);

  const commitSearch = (value: string) => {
    ownCommit.current = value;
    state.commitSearch(value);
  };

  const onSearchChange = (value: string) => {
    setSearchInput(value);
    clearTimeout(timer.current);
    timer.current = setTimeout(() => commitSearch(value), SEARCH_DEBOUNCE_MS);
  };

  const flushSearch = () => {
    clearTimeout(timer.current);
    commitSearch(searchInput);
  };

  const idle =
    props.left ??
    (showSearch ? (
      <InputGroup className="h-8 w-56">
        <InputGroupAddon>
          <Search />
        </InputGroupAddon>
        <InputGroupInput
          value={searchInput}
          placeholder={props.searchPlaceholder ?? L("Table:Search")}
          onChange={(e) => onSearchChange(e.target.value)}
          onKeyDown={(e) => e.key === "Enter" && flushSearch()}
        />
        {searchInput !== "" && (
          <InputGroupAddon align="inline-end">
            <InputGroupButton
              size="icon-xs"
              aria-label={L("Table:SearchClear")}
              // 清空是一次明确的提交，不走防抖：点了却要等 400ms 才见结果，会被当成没点上。
              onClick={() => {
                clearTimeout(timer.current);
                setSearchInput("");
                commitSearch("");
              }}
            >
              <X />
            </InputGroupButton>
          </InputGroupAddon>
        )}
      </InputGroup>
    ) : null);

  // 只有在给了 bulk 内容时才订阅选中态：没有批量内容的表，左区恒定，多挂一个订阅者没有意义。
  const left =
    props.bulk === undefined ? (
      idle
    ) : (
      <SelectedCount>{(count) => (count > 0 ? props.bulk : idle)}</SelectedCount>
    );

  return (
    <div className="flex flex-wrap items-center gap-2 border-b px-4 py-2">
      {left}
      <div className="ml-auto flex items-center gap-2">
        {props.actions}
        {props.actions ? <Separator orientation="vertical" className="mx-1 !h-5" /> : null}
        <div className="flex items-center gap-1">
          {props.utilityLeading}
          {props.onRefresh && (
            <Tooltip>
              <TooltipTrigger asChild>
                <Button
                  type="button"
                  variant="ghost"
                  size="icon"
                  className={UTILITY_ICON_CLASS}
                  aria-label={L("Table:Refresh")}
                  onClick={props.onRefresh}
                >
                  <RefreshCw className={cn(props.refreshing && "animate-spin")} />
                </Button>
              </TooltipTrigger>
              <TooltipContent>{L("Table:Refresh")}</TooltipContent>
            </Tooltip>
          )}
          {props.onExport && (
            <Tooltip>
              <TooltipTrigger asChild>
                <Button
                  type="button"
                  variant="ghost"
                  size="icon"
                  className={UTILITY_ICON_CLASS}
                  aria-label={L("Table:Export")}
                  onClick={props.onExport}
                >
                  <Download />
                </Button>
              </TooltipTrigger>
              <TooltipContent>{L("Table:Export")}</TooltipContent>
            </Tooltip>
          )}
          {props.children}
        </div>
      </div>
    </div>
  );
}

import type { HeaderContext, RowData } from "@tanstack/react-table";
import { flexRender } from "@tanstack/react-table";
import type { ReactNode } from "react";
import type { CellTableInstance, TableFeatures } from "@/components/data-table/table-core";

/** 列标签解析阶梯：meta.label → 表头 flexRender 结果（与表头逐字一致）→ 隐藏列兜底直调
 * header 渲染器 → column.id。
 *
 * 契约：列隐藏后 `getHeaderGroups()`（进而 `getFlatHeaders()`）不会给出该列的表头对象，v9
 * 引擎在 `getVisibleLeafColumns()` 就把它筛掉了。兜底分支不含真实 `header`，只拼一个
 * `{ table, column }` 上下文调用 `columnDef.header`；若你的 header 渲染器读取上下文里的
 * `header` 字段，请改设 `meta.label` 显式指定菜单文案。 */
export function resolveColumnLabel<TData extends RowData>(
  table: CellTableInstance<TData>,
  columnId: string,
): ReactNode {
  const column = table.getAllLeafColumns().find((c) => c.id === columnId);
  const metaLabel = column?.columnDef.meta?.label;
  if (metaLabel !== undefined) return metaLabel;
  const header = table.getFlatHeaders().find((h) => h.column.id === columnId);
  if (header && !header.isPlaceholder) {
    return flexRender(header.column.columnDef.header, header.getContext());
  }
  if (!column) return columnId;
  const rawHeader = column.columnDef.header;
  if (typeof rawHeader === "string") return rawHeader;
  if (typeof rawHeader === "function") {
    // 隐藏列没有 Header 实例可用；用真实 table/column 拼一个残缺上下文喂给渲染器，仅本文件内断言。
    const context = { table, column } as HeaderContext<TableFeatures, TData, unknown>;
    return rawHeader(context);
  }
  return columnId;
}

import { useLocalization } from "@jcoder-stack/abp-react/react";
import type { Column, RowData } from "@tanstack/react-table";
import { SlidersHorizontal } from "lucide-react";
import type { ReactNode } from "react";
import { resolveColumnLabel } from "@/components/data-table/column-label";
import {
  asBaseTable,
  type ExtraFeatureMap,
  type NoExtraFeatures,
  type TableFeatures,
} from "@/components/data-table/table-core";
import type { DataTableInstance } from "@/components/data-table/use-data-table";
import type { TableDensity } from "@/components/data-table/use-data-table-state";
import { Button } from "@/components/ui/button";
import { Checkbox } from "@/components/ui/checkbox";
import { Label } from "@/components/ui/label";
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover";
import { Tooltip, TooltipContent, TooltipTrigger } from "@/components/ui/tooltip";
import { cn } from "@/lib/utils";

const DEFAULT_PAGE_SIZES = [10, 20, 50];
const DENSITIES: { value: TableDensity; label: string }[] = [
  { value: "comfortable", label: "Table:DensityComfortable" },
  { value: "compact", label: "Table:DensityCompact" },
];

export interface DataTableViewMenuProps<
  TData extends RowData,
  TExtra extends ExtraFeatureMap = NoExtraFeatures,
> {
  table: DataTableInstance<TData, TExtra>;
  /** 每页条数选项，缺省 `[10, 20, 50]`。当前值与默认值总会被并入去重升序，所以传了
   *  `defaultPageSize` 忘了同步这里，也不会出现「哪一档都没选中」。 */
  pageSizes?: number[];
  /** 覆盖单列标签；缺省走 resolveColumnLabel 的三级阶梯。 */
  label?: (column: Column<TableFeatures, TData, unknown>) => ReactNode;
  className?: string;
}

function Segmented<T extends string | number>(props: {
  label: string;
  value: T;
  options: { value: T; label: ReactNode }[];
  onChange: (value: T) => void;
}) {
  return (
    <fieldset className="grid gap-1.5">
      <legend className="mb-1.5 text-muted-foreground text-xs">{props.label}</legend>
      <div className="flex divide-x overflow-hidden rounded-md border">
        {props.options.map((option) => (
          <Button
            key={option.value}
            type="button"
            variant="ghost"
            size="sm"
            aria-pressed={option.value === props.value}
            className="h-7 flex-1 rounded-none text-muted-foreground tabular-nums aria-pressed:bg-secondary aria-pressed:font-medium aria-pressed:text-foreground"
            onClick={() => props.onChange(option.value)}
          >
            {option.label}
          </Button>
        ))}
      </div>
    </fieldset>
  );
}

/** 视图设置：密度、每页条数、显示哪些列，三样「改表格外观、不改数据」的设置合在一个入口。
 *  偏离默认时触发钮带圆点，面板底部给「恢复默认视图」——偏好会被记住，得有一步回得去。
 *  出现哪些列由列定义的 `enableHiding` 原生控制，本组件不做二次过滤。 */
export function DataTableViewMenu<
  TData extends RowData,
  TExtra extends ExtraFeatureMap = NoExtraFeatures,
>(props: DataTableViewMenuProps<TData, TExtra>) {
  const L = useLocalization();
  const { state } = props.table;
  const table = asBaseTable(props.table.table);
  const columns = table.getAllLeafColumns().filter((c) => c.getCanHide());

  const pageSize = state.params.pageSize;
  const sizeOptions = [
    ...new Set([...(props.pageSizes ?? DEFAULT_PAGE_SIZES), state.defaultPageSize, pageSize]),
  ].sort((a, b) => a - b);

  const initialVisibility = table.initialState.columnVisibility;
  const customized =
    state.density !== "comfortable" ||
    pageSize !== state.defaultPageSize ||
    columns.some((c) => c.getIsVisible() !== (initialVisibility?.[c.id] ?? true));

  return (
    <Popover>
      <Tooltip>
        <TooltipTrigger asChild>
          <PopoverTrigger asChild>
            <Button
              type="button"
              variant="ghost"
              size="icon"
              className={cn("relative size-8 text-muted-foreground", props.className)}
              aria-label={L("Table:ViewSettings")}
            >
              <SlidersHorizontal />
              {customized && (
                <span
                  data-slot="view-customized"
                  className="absolute top-1 right-1 size-1.5 rounded-full bg-primary"
                />
              )}
            </Button>
          </PopoverTrigger>
        </TooltipTrigger>
        <TooltipContent>{L("Table:ViewSettings")}</TooltipContent>
      </Tooltip>
      <PopoverContent align="end" className="grid w-60 gap-3 p-3 text-sm">
        <Segmented
          label={L("Table:Density")}
          value={state.density}
          options={DENSITIES.map((d) => ({ value: d.value, label: L(d.label) }))}
          onChange={state.setDensity}
        />
        <Segmented
          label={L("Table:RowsPerPage")}
          value={pageSize}
          options={sizeOptions.map((size) => ({ value: size, label: size }))}
          onChange={(size) => table.setPagination({ pageIndex: 0, pageSize: size })}
        />
        {columns.length > 0 && (
          <fieldset className="grid">
            <legend className="mb-1.5 text-muted-foreground text-xs">
              {L("Table:ViewColumns")}
            </legend>
            {columns.map((column) => (
              <Label key={column.id} className="h-7 font-normal">
                <Checkbox
                  checked={column.getIsVisible()}
                  onCheckedChange={(value) => column.toggleVisibility(value === true)}
                />
                {props.label?.(column) ?? resolveColumnLabel(table, column.id)}
              </Label>
            ))}
          </fieldset>
        )}
        {customized && (
          <div className="border-t pt-2">
            <Button
              type="button"
              variant="link"
              size="sm"
              className="h-auto p-0"
              onClick={() => {
                table.resetColumnVisibility();
                state.resetViewDefaults();
              }}
            >
              {L("Table:ViewReset")}
            </Button>
          </div>
        )}
      </PopoverContent>
    </Popover>
  );
}

import { useLocalization } from "@jcoder-stack/abp-react/react";
import type { Column, RowData } from "@tanstack/react-table";
import { ArrowUpDown } from "lucide-react";
import type { ReactNode } from "react";
import { resolveColumnLabel } from "@/components/data-table/column-label";
import {
  asBaseTable,
  type ExtraFeatureMap,
  type NoExtraFeatures,
  type TableFeatures,
  type TableInstance,
} from "@/components/data-table/table-core";
import type { DataTableInstance } from "@/components/data-table/use-data-table";
import { Button } from "@/components/ui/button";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { Tooltip, TooltipContent, TooltipTrigger } from "@/components/ui/tooltip";
import { cn } from "@/lib/utils";

export interface DataTableSortMenuProps<
  TData extends RowData,
  TExtra extends ExtraFeatureMap = NoExtraFeatures,
> {
  table: DataTableInstance<TData, TExtra>;
  /** 菜单末尾追加自定义项；`items` 输入是完整表实例，非单列。 */
  items?: (table: TableInstance<TData, TExtra>) => ReactNode;
  /** 覆盖单列标签；缺省走 resolveColumnLabel 的三级阶梯。 */
  label?: (column: Column<TableFeatures, TData, unknown>) => ReactNode;
  className?: string;
}

/** 排序菜单：每次点选**叠加**到现有排序，不替换。已在排序中的列点了是翻方向，不在的追加到末尾。
 * 退出多列态走「清除排序」项。与表头点击的心智模型不同：表头默认替换、按住 shift 才叠加，
 * 菜单里没有 shift 手势可用，所以默认就是叠加。出现哪些列仍由列定义的 `enableSorting` 原生控制。 */
export function DataTableSortMenu<
  TData extends RowData,
  TExtra extends ExtraFeatureMap = NoExtraFeatures,
>(props: DataTableSortMenuProps<TData, TExtra>) {
  const L = useLocalization();
  const table = asBaseTable(props.table.table);
  const columns = table.getAllLeafColumns().filter((c) => c.getCanSort());

  return (
    <DropdownMenu modal={false}>
      <Tooltip>
        <TooltipTrigger asChild>
          <DropdownMenuTrigger asChild>
            <Button
              variant="ghost"
              size="icon"
              className={cn("size-8 text-muted-foreground", props.className)}
              aria-label={L("Table:Sort")}
            >
              <ArrowUpDown />
            </Button>
          </DropdownMenuTrigger>
        </TooltipTrigger>
        <TooltipContent>{L("Table:Sort")}</TooltipContent>
      </Tooltip>
      <DropdownMenuContent align="end">
        {columns.map((column) => (
          <DropdownMenuItem
            key={column.id}
            // 第二参 multi=true：菜单里点第二列不再把第一列压掉。没有它，菜单会
            // 破坏用户刚用 shift+click 建立的多列排序状态。
            onClick={() => column.toggleSorting(column.getIsSorted() === "asc", true)}
          >
            {props.label?.(column) ?? resolveColumnLabel(table, column.id)}
          </DropdownMenuItem>
        ))}
        <DropdownMenuSeparator />
        <DropdownMenuItem onClick={() => table.setSorting([])}>
          {L("Table:SortClear")}
        </DropdownMenuItem>
        {props.items?.(props.table.table)}
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

export interface DataTableClearSortButtonProps<
  TData extends RowData,
  TExtra extends ExtraFeatureMap = NoExtraFeatures,
> {
  table: DataTableInstance<TData, TExtra>;
  className?: string;
}

/** 多列排序的退出口：仅在两列及以上排序时出现，点击一次清空全部排序。
 * 可见性判据留在组件内部，调用方无条件渲染即可。「何时需要退出口」是表现层知识，
 * 不该外泄给组装层。单列排序不给出口：表头三态循环（asc→desc→无）两次点击即可退出，
 * 为它多摆一颗常驻按钮是噪声。 */
export function DataTableClearSortButton<
  TData extends RowData,
  TExtra extends ExtraFeatureMap = NoExtraFeatures,
>(props: DataTableClearSortButtonProps<TData, TExtra>) {
  const L = useLocalization();
  const table = asBaseTable(props.table.table);
  if (table.state.sorting.length <= 1) return null;

  return (
    <Button
      variant="ghost"
      size="sm"
      className={cn("text-muted-foreground", props.className)}
      onClick={() => table.setSorting([])}
    >
      {L("Table:SortClear")}
    </Button>
  );
}
